// Hand-written; qutegen never overwrites *_manual.go files.

// Package qtmultimedia binds QtMultimedia: media playback (QMediaPlayer,
// QAudioOutput, QSoundEffect), capture (QMediaCaptureSession, QCamera,
// QMediaRecorder, QImageCapture, screen and window capture), raw audio
// (QAudioSink, QAudioSource, QAudioDecoder) and video frames (QVideoSink,
// QVideoFrame). It is generated by cmd/qutegen from spec/.
//
//	player := qtmultimedia.NewQMediaPlayer(win)
//	player.SetAudioOutput(qtmultimedia.NewQAudioOutput(player))
//	player.SetSource(qtcore.NewQUrlWithUrl("file:///tmp/song.ogg"))
//	player.Play()
//
// Qt never takes ownership of what is plugged into a player or capture
// session (outputs, inputs, sinks, devices, cameras, recorders), so each
// setter keeps its argument alive while the receiver uses it. A player or
// session with no parent that keeps anything must be Deleted (qute vet's
// owned-leak check reports one that is not); give it a parent, as above, to
// have it freed with its window.
//
// QVideoFrame and QAudioBuffer count their pixel and sample bytes outside the
// Go heap, so a handler that receives many frames does not let them pile up
// between collections.
package qtmultimedia
